using System.Security.Cryptography;using System.Net;using System.Net.Sockets;using System.Text;using System.Text.Json;using System.IO;
namespace AulaControlTeacher;
public sealed class Discovery:IDisposable{readonly string key,tag;UdpClient? udp;CancellationTokenSource? cts;public event Action<Device>? Seen;public Discovery(string k){key=k;tag=AcCrypto.Sha(k)[..12];}public void Start(){cts=new();udp=new UdpClient();udp.Client.SetSocketOption(SocketOptionLevel.Socket,SocketOptionName.ReuseAddress,true);udp.Client.Bind(new IPEndPoint(IPAddress.Any,45888));_=Loop(cts.Token);}async Task Loop(CancellationToken t){while(!t.IsCancellationRequested)try{var r=await udp!.ReceiveAsync(t);using var doc=JsonDocument.Parse(Encoding.UTF8.GetString(r.Buffer));var x=doc.RootElement;if(x.GetProperty("type").GetString()!="AULACONTROL_BEACON"||x.GetProperty("schoolTag").GetString()!=tag)continue;string id=x.GetProperty("deviceId").GetString()??"",dn=x.GetProperty("deviceName").GetString()??"",u=x.GetProperty("userName").GetString()??"",co=x.GetProperty("course").GetString()??"",ip=x.GetProperty("ip").GetString()??r.RemoteEndPoint.Address.ToString();if(ip=="0.0.0.0")ip=r.RemoteEndPoint.Address.ToString();int cp=x.GetProperty("commandPort").GetInt32(),sp=x.GetProperty("screenPort").GetInt32(),bat=x.GetProperty("battery").GetInt32();bool sh=x.GetProperty("screenSharing").GetBoolean();long ts=x.GetProperty("ts").GetInt64();string sig=x.GetProperty("sig").GetString()??"";if(Math.Abs(DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()-ts)>30000)continue;string d=$"{id}\n{dn}\n{u}\n{co}\n{ip}\n{cp}\n{sp}\n{sh.ToString().ToLowerInvariant()}\n{bat}\n{ts}";if(!CryptographicOperations.FixedTimeEquals(Convert.FromHexString(AcCrypto.Hmac(key,d)),Convert.FromHexString(sig)))continue;Seen?.Invoke(new Device{Id=id,DeviceName=dn,User=u,Course=co,Model=x.GetProperty("model").GetString()??"",Android=x.GetProperty("android").GetString()??"",Ip=ip,CommandPort=cp,ScreenPort=sp,Battery=bat,Screen=sh,Seen=DateTime.Now});}catch(OperationCanceledException){break;}catch{try{await Task.Delay(150,t);}catch{}}}public void Dispose(){try{cts?.Cancel();udp?.Dispose();}catch{}}}
public class Commands(string key){public async Task<(bool,string)> Send(Device d,string a,string v=""){try{long ts=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();string sig=AcCrypto.Hmac(key,$"{a}\n{ts}\n{v}");string q=JsonSerializer.Serialize(new{action=a,ts,value=v,sig})+"\n";using var tcp=new TcpClient();using var c=new CancellationTokenSource(4000);await tcp.ConnectAsync(d.Ip,d.CommandPort,c.Token);await tcp.GetStream().WriteAsync(Encoding.UTF8.GetBytes(q),c.Token);using var sr=new StreamReader(tcp.GetStream(),Encoding.UTF8);string? line=await sr.ReadLineAsync(c.Token);if(string.IsNullOrWhiteSpace(line))return(false,"Sin respuesta");using var doc=JsonDocument.Parse(line);bool ok=doc.RootElement.GetProperty("ok").GetBoolean();return(ok,ok?"OK":doc.RootElement.TryGetProperty("error",out var e)?e.GetString()??"Error":"Error");}catch(Exception e){return(false,e.Message);}}}
